package local.snapexplorer.mobile;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Synthetic assets only; runs on the disposable emulator. */
public final class CatalogSmoke extends Instrumentation {
 private int checks;
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle r=new Bundle();try{run();r.putString("stream","PASS "+checks+" full-catalog Android checks\n");finish(Activity.RESULT_OK,r);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));r.putString("stream",s.toString());finish(Activity.RESULT_CANCELED,r);}}
 private void check(boolean v,String s){if(!v)throw new AssertionError(s);checks++;}
 private static Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void invoke(Object o,String n){runOnMainSync(()->{try{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}catch(Exception e){throw new RuntimeException(e);}});}
 private void waitIdle(Activity a)throws Exception{for(int n=0;n<300;n++){waitForIdleSync();boolean busy=a instanceof MetadataActivity?(Boolean)field(a,"busy"):(Boolean)field(a,"loading")||(Boolean)field(a,"cataloging");if(!busy){SystemClock.sleep(150);return;}SystemClock.sleep(100);}throw new AssertionError("Activity remained busy");}
 private View find(Activity a,String s){View[] v={null};runOnMainSync(()->walk(a.getWindow().getDecorView(),s,v));return v[0];}
 private static void walk(View v,String s,View[] hit){if(v instanceof TextView&&((TextView)v).getText().toString().contains(s))hit[0]=v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),s,hit);}
 private View await(Activity a,String s){for(int i=0;i<150;i++){View v=find(a,s);if(v!=null)return v;SystemClock.sleep(100);}throw new AssertionError("Missing UI: "+s);}
 private void tap(View v){runOnMainSync(()->v.performClick());waitForIdleSync();}
 private long scalar(ChatRepository repo,String sql){try(Cursor c=repo.getReadableDatabase().rawQuery(sql,null)){c.moveToFirst();return c.getLong(0);}}
 private void add(ZipOutputStream z,String path,byte[] data)throws Exception{z.putNextEntry(new ZipEntry(path));z.write(data);z.closeEntry();}
 private void asset(ZipOutputStream z,String path,String name)throws Exception{try(InputStream in=getContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);add(z,path,out.toByteArray());}}
 private int items(Activity a)throws Exception{return ((List<?>)field(a,"items")).size();}
 private void filter(Activity a,String label,int expected)throws Exception{invoke(a,"chooseKind");for(int i=0;i<100;i++){android.view.accessibility.AccessibilityNodeInfo node=getUiAutomation().getRootInActiveWindow();if(node!=null){List<android.view.accessibility.AccessibilityNodeInfo> hits=node.findAccessibilityNodeInfosByText(label);for(android.view.accessibility.AccessibilityNodeInfo h:hits)if(label.contentEquals(h.getText())){while(h!=null&&!h.isClickable())h=h.getParent();if(h==null||!h.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))continue;SystemClock.sleep(200);waitIdle(a);check(items(a)==expected,label+" filter expected "+expected+" got "+items(a));return;}}SystemClock.sleep(100);}throw new AssertionError("Missing filter "+label);}
 private void run()throws Exception{
  getUiAutomation();Context c=getTargetContext();String uuid="12345678-1234-1234-1234-123456789abc";String sticker="{\"Custom Stickers\":[{\"File\":\"custom_stickers/animated-123.gif\"},{\"Media ID\":\""+uuid+"\",\"Creator\":{\"Media ID\":\"bitmoji/avatar.png\"}},{\"Media ID\":\"missing-123456789\"}]}";
  String raw="[\"START_MARKER"+String.join("",Collections.nCopies(145000,"x"))+"END_MARKER\"]";File zip=new File(c.getCacheDir(),"full-catalog-synthetic.zip");
  try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){asset(z,"custom_stickers/animated-123.gif","animated-sticker.gif");asset(z,"chat_media/asset-"+uuid+".png","sticker.png");asset(z,"bitmoji/avatar.png","avatar.png");asset(z,"memories/overlay-x.png","overlay.png");add(z,"custom_stickers/original.svg","<svg xmlns=\"http://www.w3.org/2000/svg\"/>".getBytes(StandardCharsets.UTF_8));add(z,"attachments/document.pdf","%PDF-1.4 synthetic".getBytes(StandardCharsets.UTF_8));add(z,"json/custom_stickers.json",sticker.getBytes(StandardCharsets.UTF_8));add(z,"json/unknown_dataset.json",raw.getBytes(StandardCharsets.UTF_8));}
  ChatRepository repo=new ChatRepository(c);repo.importArchives(Collections.singletonList(new ChatRepository.Input(zip,"Synthetic full catalog",false)),true,(a,b)->{});ExportCatalog.ensure(repo,(a,b)->{});
  check(scalar(repo,"SELECT COUNT(*) FROM media")==6,"All supported and save-only assets retained");check(scalar(repo,"SELECT COUNT(*) FROM asset_tags WHERE role='sticker'")==3,"Explicit IDs tag opaque media as stickers");check(scalar(repo,"SELECT COUNT(*) FROM asset_tags WHERE role='avatar'")==1,"Avatar role retained");check(scalar(repo,"SELECT COUNT(*) FROM asset_tags WHERE role='overlay'")==1,"Overlay role retained");check(scalar(repo,"SELECT records FROM dataset_catalog WHERE category='Stickers'")==3,"Every sticker metadata record catalogued");check(scalar(repo,"SELECT matched FROM dataset_catalog WHERE category='Stickers'")==2,"Only existing local sticker references matched");check(scalar(repo,"SELECT COUNT(*) FROM metadata")==2,"Unknown dataset retained");repo.importArchives(Collections.singletonList(new ChatRepository.Input(zip,"Synthetic replacement with same counts",false)),true,(a,b)->{});ExportCatalog.ensure(repo,(a,b)->{});check(scalar(repo,"SELECT COUNT(*) FROM asset_tags WHERE role='sticker'")==3,"Replacement with identical counts rebuilds tags");
  String gif="",unknown="";try(Cursor cur=repo.getReadableDatabase().rawQuery("SELECT id FROM media WHERE name LIKE '%.gif'",null)){cur.moveToFirst();gif=cur.getString(0);}try(Cursor cur=repo.getReadableDatabase().rawQuery("SELECT id FROM metadata WHERE filename LIKE '%unknown%'",null)){cur.moveToFirst();unknown=cur.getString(0);}repo.close();
  Activity gallery=startActivitySync(new Intent(c,MediaActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitIdle(gallery);check(items(gallery)==6,"General gallery includes all six local assets");filter(gallery,"Stickers",3);filter(gallery,"Bitmoji & avatars",1);filter(gallery,"Overlays",1);filter(gallery,"Other files",2);tap(await(gallery,"Reset filters"));waitIdle(gallery);check(items(gallery)==6,"Reset restores all assets");runOnMainSync(gallery::finish);
  Activity viewer=startActivitySync(new Intent(c,MediaActivity.class).putExtra("media_id",gif).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<150&&field(viewer,"animation")==null;i++)SystemClock.sleep(100);android.graphics.drawable.Animatable animation=(android.graphics.drawable.Animatable)field(viewer,"animation");check(animation!=null&&animation.isRunning(),"Local GIF actually animates");View[] image={null};runOnMainSync(()->findAnimation(viewer.getWindow().getDecorView(),image));tap(image[0]);check(!animation.isRunning(),"Tap pauses animated sticker");tap(image[0]);check(animation.isRunning(),"Tap resumes animated sticker");runOnMainSync(viewer::finish);for(int i=0;i<100&&animation.isRunning();i++)SystemClock.sleep(100);check(!animation.isRunning(),"Leaving viewer stops animation");
  Activity data=startActivitySync(new Intent(c,MetadataActivity.class).putExtra("dataset_id",unknown).putExtra("filename","unknown_dataset.json").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitIdle(data);await(data,"START_MARKER");check(find(data,"END_MARKER")==null,"Raw JSON is paged with bounded memory");int pages=1;while(find(data,"END_MARKER")==null&&pages<10){tap(await(data,"Next"));waitIdle(data);pages++;}check(find(data,"END_MARKER")!=null&&pages>5,"Unknown scalar array readable past old preview limit");check(!await(data,"Next").isEnabled(),"End of dataset disables next");tap(await(data,"Previous"));waitIdle(data);check(await(data,"Next").isEnabled(),"Previous raw JSON page remains navigable");check((data.getWindow().getAttributes().flags&0x2000)==0,"Data browser permits screenshots");File saved=new File(c.getCacheDir(),"synthetic-full-json-save.json");if(saved.exists()&&!saved.delete())throw new AssertionError("Could not clear synthetic save destination");final String savedId=unknown;runOnMainSync(()->{try{Field f=data.getClass().getDeclaredField("pendingId");f.setAccessible(true);f.set(data,savedId);((MetadataActivity)data).onActivityResult(91,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(saved)));}catch(Exception e){throw new RuntimeException(e);}});for(int i=0;i<150&&saved.length()!=raw.getBytes(StandardCharsets.UTF_8).length;i++)SystemClock.sleep(100);ByteArrayOutputStream copied=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(saved)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)copied.write(buffer,0,n);}check(Arrays.equals(copied.toByteArray(),raw.getBytes(StandardCharsets.UTF_8)),"Save full JSON preserves every byte beyond visible page");runOnMainSync(data::finish);
 }
 private static void findAnimation(View v,View[] out){if("Animated image · tap to pause or play".equals(v.getContentDescription()))out[0]=v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)findAnimation(((ViewGroup)v).getChildAt(i),out);}
}
